input.command:
$base = "D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\data"
Write-Host "=== MAIN inbound.jsonl (last 40 telegram-ish / recent) ==="
Get-Content "$base\logs\inbound.jsonl" -Tail 80 | ForEach-Object {
  try {
    $o = $_ | ConvertFrom-Json
    $ch = [string]$o.channelId
    $src = [string]$o.source
    if ($src -match 'telegram' -or $ch -match 'telegram|6644482344|3868178598' -or $o.platform -match 'telegram') {
      $_
    }
  } catch {}
} | Select-Object -Last 40

Write-Host "`n=== FERN FOREST vault inbound (last 30) ==="
Get-Content "$base\telegram\groups\-1003868178598\inbound.jsonl" -Tail 30

Write-Host "`n=== utterances/turns recent ==="
Get-ChildItem "$base" -Recurse -Include "*utterance*","*turns*","*outbound*" -ErrorAction SilentlyContinue | Select-Object FullName, Length, LastWriteTime | Format-Table -AutoSize
Get-ChildItem "$base\logs" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 25 Name, Length, LastWriteTime
Get-ChildItem "$base\telegram" -Recurse -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 40 FullName, Length, LastWriteTime | Format-Table -AutoSize

$base = "D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\data"
# What did pipeline already say to 15339/15343?
Write-Host "=== utterances for 15339/15343 ==="
Select-String -Path "$base\training\utterances.jsonl" -Pattern '"refId":"15339"|"refId":"15343"|messageId":"15339"|messageId":"15343"' | Select-Object -Last 10
Write-Host "`n=== actions tail ==="
Get-Content "$base\logs\actions.jsonl" -Tail 12 | ForEach-Object {
  $o = $_ | ConvertFrom-Json
  if ($o.type -eq 'ava.utterance' -or $o.channelId -match '3868178598') {
    "$($o.type) msg=$($o.messageId) kind=$($o.kind) src=$($o.source) ref-ish chars=$($o.chars)"
  } else { "$($o.type)" }
}
Write-Host "`n=== full inbound 15339 15343 ==="
Get-Content "$base\logs\inbound.jsonl" | Where-Object { $_ -match '"messageId":"15339"|"messageId":"15343"' }
